import{z as p,x as o,o as r,c as A,q as n,j as E,D as e,d as s,s as l,S as d,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"分布式追踪","description":"","frontmatter":{"title":"分布式追踪","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/distributed-tracing.md","filePath":"cs/distributed-tracing.md","lastUpdated":1791063341000}'),B={name:"cs/distributed-tracing.md"};function c(m,a,h,u,D,T){const i=o("Mermaid");return r(),A("div",null,[a[2]||(a[2]=n('<h1 id="分布式追踪" tabindex="-1">分布式追踪 <a class="header-anchor" href="#分布式追踪" aria-label="Permalink to &quot;分布式追踪&quot;">​</a></h1><div class="epigraph"><p>一次请求跨许多进程，把因果边采成 span 树。采样与传播头让你看见扇出，不是代替[向量时钟](/cs/vector-clocks)的完备偏序。</p><footer>—— 据 Sigelman et al., Dapper, a Large-Scale Distributed Systems Tracing Infrastructure, Google 技术报告 2010 整理</footer></div><p>上一课<a href="/cs/lb-strategies">负载均衡</a>把请求打散。缺口是<strong>一次用户调用变成哪些 RPC</strong>：过载与错误发生在哪一跳。本课钉 Dapper 式追踪：trace id、span、采样。后课三支柱把日志与指标接上。不重写 happened-before 定理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Dapper：前端生成 trace id，沿 RPC 传播；每跳一个 span，父子边是调用。采样：全量太贵，按树决策（根决定采不采）保持一棵树完整。缺口：追踪是调试与容量的观察，不是线性一致证明。时钟用墙钟画甘特，跨机可能倒序——接<a href="/cs/clock-drift">时钟漂移</a>，边靠传播的父子关系，不靠 NTP。</p><p>与日志：日志无跨进程 id 则拼不出树。与指标：指标无单次请求。</p><p><span class="marginnote">术语翻译：trace id 是给这次请求发的唯一编号，像挂号信单号，走一路被抄在每一站的台账上；span 是其中一站的条目——谁发起、打给谁、何时开始何时结束。靠这个单号才能把几百条台账拼回一棵调用树。</span></p><p><span class="marginnote">2010 技术报告是工业源头。OpenTelemetry 是后来的 API 收敛，本课点名不写规范全书。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>埋点在 RPC 桩与队列消费者：取出/注入上下文。异步消息要把 trace 放进消息头，否则 Saga 步骤断链。采样率可动态，错误路径可强制采。</p>',10)),(r(),E(d,null,{default:e(()=>[l(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E6%A0%B9%20span%22%5D%20--%3E%20A%5B%22%E6%9C%8D%E5%8A%A1%20A%22%5D%0A%20%20ROOT%20--%3E%20B%5B%22%E6%9C%8D%E5%8A%A1%20B%22%5D%0A%20%20A%20--%3E%20C%5B%22%E5%AD%98%E5%82%A8%22%5D%0A%20%20CTX%5B%22trace%20%E4%B8%8A%E4%B8%8B%E6%96%87%E4%BC%A0%E6%92%AD%22%5D%20--%3E%20ROOT%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"不要只在成功路径埋点。失败跳往往没 span，最需要看。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[s("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"Head-based 采样：根决定，便宜，可能漏稀有错误。Tail-based：先全量收再决定留哪些，贵，能留异常树。生产常混合。高基数标签（user id）会把追踪后端打成热键——接上一课序。",-1)),(r(),E(d,null,{default:e(()=>[l(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%AF%8F%E4%B8%AA%E8%AF%B7%E6%B1%82%E8%BF%9B%E6%9D%A5%22%5D%20--%3E%20HB%5B%22head-based%EF%BC%9A%E5%85%A5%E5%8F%A3%E5%B0%B1%E6%8E%B7%E9%AA%B0%E5%AD%90%22%5D%0A%20%20Q%20--%3E%20TB%5B%22tail-based%EF%BC%9A%E5%85%88%E5%85%A8%E9%87%8F%E6%94%B6%E9%9B%86%22%5D%0A%20%20HB%20--%3E%20C1%5B%22%E5%8F%AA%E7%95%99%E7%BA%A6%201%25%EF%BC%8C%E4%BE%BF%E5%AE%9C%22%5D%0A%20%20HB%20--%3E%20L1%5B%22%E7%A8%80%E6%9C%89%E9%94%99%E8%AF%AF%E5%A4%A7%E6%A6%82%E7%8E%87%E6%BC%8F%E9%87%87%22%5D%0A%20%20TB%20--%3E%20C2%5B%22%E5%90%8E%E7%AB%AF%E5%A4%9A%E6%89%9B%E5%85%A8%E9%87%8F%EF%BC%8C%E8%B4%B5%22%5D%0A%20%20TB%20--%3E%20K2%5B%22%E8%83%BD%E5%AE%8C%E6%95%B4%E4%BF%9D%E7%95%99%E6%85%A2%E6%A0%91%E4%B8%8E%E5%87%BA%E9%94%99%E6%A0%91%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">数字实例：head-based 采样率 1% 意味着每秒 1 万次请求只留下约 100 棵完整 trace，那 5 小时才出现一次的 500 错误大概率被扔掉；tail-based 是把 1 万棵都先收齐，再挑出带错误或最慢的几十棵保存——代价是后端多扛全量带宽。</span></p><p><span class="marginnote">常见误区：初学者容易看着 trace 甘特图断言「B 一定发生在 A 之后」，因为图上时间轴如此。跨机墙钟会漂移，图上的先后可能倒错；真正可信的只有「A 调用了 B」这条父子边——它是随请求传播出来的因果，不依赖任何时钟。</span></p><p>本课不写 Zipkin 全部 UI。也不把追踪当安全审计完整解（缺不可伪造）。</p><p>因果：span 父子 ⊂ happened-before，但未埋点的边看不见。不能用追踪图当 Chandy–Lamport 快照。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把指标仪表盘画全。后课默认：跨服务排障先跟 trace id；时钟只用来显示，边用传播。可观测三支柱下一课说明三者不可互相替代。</p><p>看见扇出才能解释 P99。看不见的边等于不存在于调试里。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Trace/span 树靠上下文传播，不靠 NTP 排序。</li><li>采样保整树；错误路径要能强制采。</li><li>观察工具不是一致性证明。</li><li>出处：Sigelman et al., Dapper, 2010。</li></ul>',9))])}const C=p(B,[["render",c]]);export{f as __pageData,C as default};
